INSERT INTO `email_verifier_items` (`id`, `section`, `badge_key`, `icon`, `title`, `description`, `is_highlight`, `sr_order`, `lang`, `status`, `created_at`, `updated_at`) VALUES
(1, 'trust', NULL, 'mail-x', 'No email ever delivered', NULL, 0, 0, 'en_US', 'draft', '2026-09-09 12:22:40', '2026-09-10 07:35:47'),
(2, 'trust', NULL, 'server', 'Live mail server check', NULL, 0, 1, 'en_US', 'draft', '2026-09-09 12:22:40', '2026-09-10 07:35:47'),
(3, 'trust', NULL, 'shield-check', 'GDPR-aware', NULL, 0, 2, 'en_US', 'draft', '2026-09-09 12:22:40', '2026-09-10 07:35:47'),
(4, 'trust', NULL, 'lock', 'SSL secured', NULL, 0, 3, 'en_US', 'draft', '2026-09-09 12:22:40', '2026-09-10 07:35:47'),
(5, 'check', NULL, 'spell-check', 'Syntax validation', 'Catches typos and malformed addresses before they ever cost you a send.', 0, 4, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(6, 'check', NULL, 'server', 'MX record lookup', 'Confirms the domain actually has mail servers configured to receive email.', 0, 5, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(7, 'check', NULL, 'globe', 'Domain health', 'Verifies the domain resolves properly and is set up to accept mail.', 0, 6, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(8, 'check', NULL, 'trash-2', 'Disposable detection', 'Flags throwaway inboxes built to disappear within minutes of signup.', 0, 7, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(9, 'check', NULL, 'users', 'Role account detection', 'Identifies shared inboxes like info@ and support@ that skew engagement.', 0, 8, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(10, 'check', NULL, 'at-sign', 'Free provider detection', 'Tells you when an address is personal rather than a company domain.', 0, 9, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(11, 'check', NULL, 'layers', 'Catch-all detection', 'Spots domains that accept everything, so you know when a result is unconfirmed.', 0, 10, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(12, 'check', NULL, 'plug-zap', 'Live mailbox check', 'Connects to the real mail server and asks whether that mailbox exists.', 0, 11, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(13, 'check', NULL, 'shield-check', 'Bounce prediction', 'Combines every signal above into one clear verdict you can act on.', 0, 12, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(14, 'glossary', 'valid', 'check-circle-2', 'Valid', 'The mailbox exists and is safe to send to.', 0, 13, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(15, 'glossary', 'invalid', 'x-circle', 'Invalid', 'The address doesn\'t exist, or the domain can\'t receive mail at all.', 0, 14, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(16, 'glossary', 'catch_all', 'layers', 'Catch-All', 'The domain accepts mail for any address, so this one mailbox stays unconfirmed.', 0, 15, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(17, 'glossary', 'disposable', 'trash-2', 'Disposable', 'A known temporary or throwaway email provider.', 0, 16, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(18, 'glossary', 'role_based', 'users', 'Role-Based', 'A shared inbox like info@ or support@ rather than a named person.', 0, 17, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(19, 'glossary', 'unknown', 'help-circle', 'Unknown', 'Format and domain look fine, but the mailbox itself could not be confirmed right now.', 0, 18, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(20, 'step', NULL, NULL, 'Invalid emails bounce', 'Every bad address comes straight back as a hard bounce, a wasted send and a wasted opportunity.', 0, 19, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(21, 'step', NULL, NULL, 'Bounces trip the filters', 'Mailbox providers watch your bounce rate closely. A high one marks you as a likely spammer.', 0, 20, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(22, 'step', NULL, NULL, 'Reputation blocks delivery', 'Once your sender reputation drops, even your genuinely good emails stop reaching the inbox.', 0, 21, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40'),
(23, 'step', NULL, NULL, 'Clean lists fix all three', 'Verified lists mean better delivery, higher open rates and a lower cost per real lead.', 1, 22, 'en_US', 'publish', '2026-09-09 12:22:40', '2026-09-09 12:22:40');
